{"code": "import pandas as pd
from datetime import datetime
df = pd.read_excel('DonHang_ChiTiet_1.xlsx', sheet_name='T03-2026', usecols='A:B,C')
df.columns = ['ma_don', 'ngay_dat', 'trang_thai']
df = df[df['ma_don'].astype(str).str.contains('Mã|Trạng', case=False, na=False) == False]
strings = df['ngay_dat'].dropna().astype(str)
# find non-dd/mm/yyyy strings
import re
def is_ddmmyy(s):
    return bool(re.match(r'^\d{2}/\d{2}/\d{4}$', s))
non = strings[~strings.apply(is_ddmmyy)]
print("non-dd/mm/yyyy strings:", non.value_counts().head(20))
print("total non-dd/mm/yyyy:", len(non))

# test parse on a sample
for s in ['01/03/2026', '30/03/2026']:
    try:
        print(s, datetime.strptime(s, '%d/%m/%Y'))
    except Exception as e:
        print(s, "ERR", e)
"}

